<script>
(function(){
'use strict';

/* ======================== COIN RENDERING ENGINE ======================== */

const hero = document.getElementById('coin-hero');
const ctx = hero.getContext('2d');

function resizeHero(){
  const s = Math.min(window.innerWidth * 0.8, window.innerHeight * 0.6, 600);
  const dpr = window.devicePixelRatio || 1;
  hero.width = s * dpr;
  hero.height = s * dpr;
  hero.style.width = s + 'px';
  hero.style.height = s + 'px';
  ctx.setTransform(dpr,0,0,dpr,0,0);
}
resizeHero();
window.addEventListener('resize', resizeHero);

const W = () => hero.clientWidth;
const H = () => hero.clientHeight;
const CX = () => W() / 2;
const CY = () => H() / 2;
const coinR = () => Math.min(W(),H()) * 0.42; // radius in px

// Metal colors for different finishes
const metalFins = {
  gold:   {face:'#d4a843', faceLight:'#f5dda0', faceDark:'#8b6914', edge:'#c9a84c', rim:'#e8c85a'},
  bronze:{face:'#b87333', faceLight:'#db9f5e', faceDark:'#7a4a1a', edge:'#a0622e', rim:'#d4915a'},
  silver:{face:'#c8c8c8', faceLight:'#eaeaea', faceDark:'#888', edge:'#aaa', rim:'#ddd'},
  black: {face:'#1a1a1a', faceLight:'#3a3a3a', faceDark:'#080808', edge:'#2a2a2a', rim:'#444'}
};

/* 3D math helpers */
function vec3(x,y,z){return{x,y,z}}
function rotateY(v,a){const c=Math.cos(a),s=Math.sin(a);return vec3(v.x*c+v.z*s,v.y,-v.x*s+v.z*c)}
function rotateX(v,a){const c=Math.cos(a),s=Math.sin(a);return vec3(v.x,v.y*c-v.z*s,v.y*s+v.z*c)}
function cross(a,b){return vec3(a.y*b.z-a.z*b.y,a.z*b.x-a.x*b.z,a.x*b.y-a.y*b.x)}
function dot(a,b){return a.x*b.x+a.y*b.y+a.z*b.z}
function normalize(v){const l=Math.sqrt(dot(v,v))||1;return vec3(v.x/l,v.y/l,v.z/l)}

/* Draw emblem on coin face */
function drawEmblem(ctx,cx,cy,r,type,metal,alpha){
  ctx.save();
  ctx.globalAlpha = alpha || 1;
  ctx.translate(cx,cy);

  // Outer decorative ring
  ctx.strokeStyle = metal.faceDark;
  ctx.lineWidth = r * 0.025;
  ctx.beginPath(); ctx.arc(0,0,r*0.92,0,Math.PI*2); ctx.stroke();

  // Inner decorative ring
  ctx.strokeStyle = metal.rim;
  ctx.lineWidth = r * 0.015;
  ctx.beginPath(); ctx.arc(0,0,r*0.85,0,Math.PI*2); ctx.stroke();

  // Dotted border
  const dots = 72;
  for(let i=0;i<dots;i++){
    const a = (i/dots)*Math.PI*2 - Math.PI/2;
    const dr = r*0.95;
    const px = Math.cos(a)*dr;
    const py = Math.sin(a)*dr;
    ctx.fillStyle = metal.rim;
    ctx.globalAlpha = 0.6 * (alpha||1);
    ctx.beginPath(); ctx.arc(px,py,r*0.008,0,Math.PI*2); ctx.fill();
  }
  ctx.globalAlpha = alpha || 1;

  // Central emblem area - raised circle background
  const grad = ctx.createRadialGradient(0,0,r*0.3,0,0,r*0.65);
  grad.addColorStop(0, metal.faceLight + '40');
  grad.addColorStop(1, metal.faceDark + '20');
  ctx.fillStyle = grad;
  ctx.beginPath(); ctx.arc(0,0,r*0.65,0,Math.PI*2); ctx.fill();

  // Star / diamond emblem (center)
  const starR = r * 0.22;
  ctx.fillStyle = metal.rim;
  ctx.shadowColor = 'rgba(0,0,0,0.3)';
  ctx.shadowBlur = r*0.03;
  ctx.beginPath();
  for(let i=0;i<6;i++){
    const a = (i/6)*Math.PI*2 - Math.PI/2;
    const px = Math.cos(a)*starR;
    const py = Math.sin(a)*starR;
    if(i===0) ctx.moveTo(px,py); else ctx.lineTo(px,py);
  }
  ctx.closePath(); ctx.fill();
  ctx.shadowBlur = 0;

  // Inner diamond
  ctx.strokeStyle = metal.faceDark + '80';
  ctx.lineWidth = r*0.02;
  const dR = starR*0.55;
  ctx.beginPath();
  ctx.moveTo(0,-dR); ctx.lineTo(dR,0); ctx.lineTo(0,dR); ctx.lineTo(-dR,0); ctx.closePath();
  ctx.stroke();

  // WTM initials in center
  ctx.fillStyle = metal.faceDark + 'aa';
  ctx.font = `bold ${r*0.14}px Georgia`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('W·T·M', 0, r*0.05);

  // Top arc text: "WASTEDTOKEN MINT"
  const topArcR = r * 0.72;
  const textTop = 'WASTEDTOKEN';
  const textBot = 'MINT';

  ctx.fillStyle = metal.faceDark + 'cc';
  const fontSize = r * 0.1;
  ctx.font = `bold ${fontSize}px Georgia`;

  // Draw text along top arc
  const topStartAngle = -Math.PI * 0.75;
  const topEndAngle = -Math.PI * 0.25;
  const topMid = (topStartAngle + topEndAngle) / 2;

  for(let i=0;i<textTop.length;i++){
    const frac = (i+0.5)/textTop.length;
    const a = topStartAngle + frac*(topEndAngle - topStartAngle);
    const px = Math.cos(a)*topArcR;
    const py = Math.sin(a)*topArcR;
    ctx.save();
    ctx.translate(px,py);
    ctx.rotate(a + Math.PI/2);
    ctx.fillText(textTop[i],0,0);
    ctx.restore();
  }

  // Bottom arc text
  const botStartAngle = Math.PI * 0.75;
  const botEndAngle = Math.PI * 1.25;

  for(let i=0;i<textBot.length;i++){
    const frac = (i+0.5)/textBot.length;
    const a = botStartAngle + frac*(botEndAngle - botStartAngle);
    const px = Math.cos(a)*topArcR;
    const py = Math.sin(a)*topArcR;
    ctx.save();
    ctx.translate(px,py);
    ctx.rotate(a + Math.PI/2);
    ctx.fillText(textBot[i],0,0);
    ctx.restore();
  }

  // Laurel wreath decoration - simplified as two curved branches
  ctx.strokeStyle = metal.rim + '60';
  ctx.lineWidth = r*0.012;

  // Left wreath
  for(let i=0;i<12;i++){
    const a = Math.PI*0.5 + (i/12)*Math.PI*0.45;
    const wr = r*0.78;
    const lx = -Math.cos(a)*wr;
    const ly = Math.sin(a)*wr*0.6;
    ctx.beginPath();
    ctx.ellipse(lx,ly,r*0.03,r*0.015,a+Math.PI/4,0,Math.PI*2);
    ctx.fillStyle = metal.rim + '40';
    ctx.fill();
  }

  // Right wreath
  for(let i=0;i<12;i++){
    const a = Math.PI*0.5 + (i/12)*Math.PI*0.45;
    const wr = r*0.78;
    const lx = Math.cos(a)*wr;
    const ly = Math.sin(a)*wr*0.6;
    ctx.beginPath();
    ctx.ellipse(lx,ly,r*0.03,r*0.015,-a-Math.PI/4,0,Math.PI*2);
    ctx.fillStyle = metal.rim + '40';
    ctx.fill();
  }

  // Small stars as decoration between text arcs
  for(let i=0;i<4;i++){
    const angles = [-0.6, -0.3, 0.3, 0.6];
    const a = angles[i];
    const sr = r*0.82;
    ctx.fillStyle = metal.rim + '80';
    const sx = Math.sin(a)*sr;
    const sy = -Math.cos(a)*sr*0.15 - r*0.45;
    drawStar(ctx,sx,sy,r*0.03,5);
  }

  ctx.restore();
}

function drawBackFace(ctx,cx,cy,r,type,metal,alpha){
  ctx.save();
  ctx.globalAlpha = alpha || 1;
  ctx.translate(cx,cy);

  // Denomination text
  const denomTexts = {gold:'50,000 TOKENS',silver:'10,000 TOKENS',bronze:'5,000 TOKENS',black:'100,000 TOKENS'};
  const denom = denomTexts[type] || '10,000 TOKENS';

  // Outer ring
  ctx.strokeStyle = metal.faceDark;
  ctx.lineWidth = r*0.03;
  ctx.beginPath(); ctx.arc(0,0,r*0.88,0,Math.PI*2); ctx.stroke();

  ctx.strokeStyle = metal.rim;
  ctx.lineWidth = r*0.015;
  ctx.beginPath(); ctx.arc(0,0,r*0.83,0,Math.PI*2); ctx.stroke();

  // Raised center circle
  const cGrad = ctx.createRadialGradient(0,0,r*0.2,0,0,r*0.6);
  cGrad.addColorStop(0, metal.faceLight + '30');
  cGrad.addColorStop(1, metal.faceDark + '15');
  ctx.fillStyle = cGrad;
  ctx.beginPath(); ctx.arc(0,0,r*0.6,0,Math.PI*2); ctx.fill();

  // Denomination number
  const numPart = denom.split(',')[0];
  ctx.fillStyle = metal.faceDark + 'dd';
  ctx.font = `bold ${r*0.18}px Georgia`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(numPart, 0, -r*0.08);

  // "TOKENS" below
  ctx.fillStyle = metal.faceDark + 'aa';
  ctx.font = `bold ${r*0.1}px Georgia`;
  ctx.fillText('TOKENS', 0, r*0.15);

  // Decorative lines above and below denomination
  ctx.strokeStyle = metal.rim + '60';
  ctx.lineWidth = r*0.01;
  ctx.beginPath(); ctx.moveTo(-r*0.3,-r*0.28); ctx.lineTo(r*0.3,-r*0.28); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(-r*0.3,r*0.35); ctx.lineTo(r*0.3,r*0.35); ctx.stroke();

  // WastedToken Mint on back too (smaller)
  ctx.fillStyle = metal.faceDark + '60';
  ctx.font = `${r*0.055}px Georgia`;
  ctx.fillText('WASTEDTOKEN MINT', 0, r*0.42);

  // Small star at bottom
  drawStar(ctx, 0, -r*0.38, r*0.04, 5);

  ctx.restore();
}

function drawStar(ctx,x,y,r,n){
  ctx.beginPath();
  for(let i=0;i<n*2;i++){
    const a = (i/(n*2))*Math.PI*2 - Math.PI/2;
    const rr = i%2===0 ? r : r*0.4;
    const px = x+Math.cos(a)*rr;
    const py = y+Math.sin(a)*rr;
    if(i===0) ctx.moveTo(px,py); else ctx.lineTo(px,py);
  }
  ctx.closePath(); ctx.fill();
}

/* Draw reeded edge */
function drawReededEdge(ctx,cx,cy,radius,tiltAngle,metal,alpha,coinTiltX){
  // When the coin is tilted (not face-on), show reeded edge as a vertical band
  const edgeVisible = Math.abs(Math.sin(coinTiltX));
  if(edgeVisible < 0.05) return;

  ctx.save();
  ctx.globalAlpha = alpha * edgeVisible * 0.6;

  // Compute the visible width of the edge band
  const edgeWidth = radius * 0.04;
  const reeds = Math.floor(radius / 3);

  for(let i=0;i<reeds;i++){
    const angle = (i/reeds)*Math.PI*2;
    // Project to screen - we only show when coin is tilted
    const nx = Math.cos(angle) * radius;

    // Edge height in screen space depends on tilt
    const edgeH = radius * Math.sin(coinTiltX);
    if(Math.abs(edgeH) < 1) continue;

    // Determine if this reed is on the visible side
    const coinRotY = getOrientation().yaw;
    const cosAngle = Math.cos(angle - coinRotY);
    if(cosAngle < 0.3) continue; // only front-facing reeds

    const px = cx + nx * Math.cos(coinRotY);

    // Draw each reed as a small vertical line
    ctx.fillStyle = metal.rim + '80';
    const x1 = px - radius*0.006;
    const x2 = px + radius*0.006;
    ctx.fillRect(x1, cy-edgeH/2, x2-x1, edgeH);
  }

  // Edge band (metallic rim between faces)
  ctx.restore();
}

/* Get current orientation */
function getOrientation(){
  const t = currentT || 0;
  return {
    yaw:   t * Math.PI * 2,      // full rotation around Y
    pitch: (Math.sin(t*Math.PI*2)*0.5+0.5) * Math.PI * 0.95 - Math.PI*0.475  // flip back and forth
  };
}

/* Render the main hero coin at time t */
function renderCoin(ctx, cx, cy, r, t){
  const {yaw, pitch} = getOrientationAt(t);

  // The face normal after rotation (originally pointing +Z)
  let normal = vec3(0,0,1);
  normal = rotateY(normal, yaw);
  normal = rotateX(normal, pitch);

  // Face visibility based on normal Z component
  const frontVis = Math.max(0, normal.z);
  const backVis = Math.max(0, -normal.z);

  // Projected ellipse parameters
  // After rotating around Y then X, the circle in XY plane becomes an ellipse
  const cosY = Math.cos(yaw);
  const cosP = Math.cos(pitch);
  const sinP = Math.sin(pitch);

  // Foreshortening of the face
  const scaleX = Math.abs(cosY);
  const scaleY = cosP;

  // Only draw if somewhat visible
  if(Math.abs(scalX) < 0.01 && Math.abs(scaleY) < 0.01) return;

  ctx.save();
  ctx.translate(cx, cy);

  // === RENDER ORDER: back face -> edge -> front face ===

  // Back face (draw first so it's behind)
  if(backVis > 0.01){
    const backMetal = metalFins.gold; // default gold-ish for hero
    drawBackFaceForHero(ctx, r, t);
  }

  // Edge band / reeded edge
  renderEdge(ctx, r, yaw, pitch);

  // Front face
  if(frontVis > 0.01){
    drawFrontFaceForHero(ctx, r, yaw, pitch, t);
  }

  ctx.restore();
}

/* Actually let me redo this with a cleaner approach - a proper cylinder renderer */

function getOrientationAt(t){
  const yaw   = t * Math.PI * 2;
  const pitch = (Math.sin(t*Math.PI*2)*0.5+0.5) * Math.PI * 1.2 - Math.PI*0.6;
  return {yaw, pitch};
}

function renderEdge(ctx, r, yaw, pitch){
  // Draw the reeded edge as a band around the coin when tilted
  const tilt = pitch;
  const edgeHeight = Math.abs(Math.sin(tilt)) * r * 0.12; // thickness of edge visible

  if(edgeHeight < 1) return;

  const cosYaw = Math.cos(yaw);
  const sinYaw = Math.sin(yaw);

  // The edge forms a band at the perimeter when coin is tilted
  // Draw concentric bands to simulate metallic rim

  for(let b=0;b<3;b++){
    const bandR = r * (0.97 - b*0.015);
    ctx.strokeStyle = metalFins.gold.rim;
    ctx.globalAlpha = 0.15 + b*0.1;
    ctx.lineWidth = edgeHeight + b*2;

    // The edge is visible as an ellipse at the perimeter
    const innerR = r * (0.94 - b*0.01);
    const outerR = r * (0.99 + b*0.01);

    ctx.beginPath();
    ctx.ellipse(0, 0, outerR, outerR * Math.abs(Math.cos(pitch)), yaw, 0, Math.PI*2);
    ctx.fillStyle = metalFins.gold.edge + '20';
    ctx.fill();

    ctx.beginPath();
    ctx.ellipse(0, 0, innerR, innerR * Math.abs(Math.cos(pitch)), yaw, 0, Math.PI*2);
    ctx.globalCompositeOperation = 'destination-out';
    ctx.fillStyle = '#000';
    ctx.fill();
    ctx.globalCompositeOperation = 'source-over';
  }

  // Reed lines on visible edge surface
  const reeds = 64;
  for(let i=0;i<reeds;i++){
    const a = (i/reeds)*Math.PI*2;
    const cosA = Math.cos(a);

    // Only show reeds on the side facing somewhat toward camera
    const frontFacing = Math.cos(a - yaw) > -0.3;
    if(!frontFacing) continue;

    const x1 = cosA * r * 0.94;
    const y1 = sinA * r * 0.94 * Math.abs(Math.cos(pitch));

    // Project the edge thickness
    const dx = Math.sin(a - yaw) * edgeHeight;

    ctx.strokeStyle = metalFins.gold.rim + '30';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x1 + dx*0.2, y1);
    ctx.stroke();
  }
}

function drawFrontFaceForHero(ctx, r, yaw, pitch, t){
  const cosPitch = Math.cos(pitch);
  const projY = r * Math.abs(cosPitch); // foreshortened height

  if(projY < 1) return;

  ctx.save();

  // Metallic base gradient that shifts with rotation
  const metal = metalFins.gold;

  // Shift highlight based on yaw angle - this creates the "raking" effect
  const highlightAngle = yaw * 0.5 + Math.PI * 0.25;
  const hlX = Math.cos(highlightAngle) * r * 0.35;
  const hlY = Math.sin(highlightAngle) * projY * 0.35;

  // Base face gradient (metallic look)
  const baseGrad = ctx.createRadialGradient(
    r*0.1, -r*0.1, r*0.05,
    0, 0, r
  );
  baseGrad.addColorStop(0, metal.faceLight);
  baseGrad.addColorStop(0.4, metal.face);
  baseGrad.addColorStop(0.8, metal.faceDark);
  baseGrad.addColorStop(1, metal.faceDark);

  // Move highlight based on rotation - the raking specular effect
  const specAngle = yaw * 0.7 + Math.PI * 0.5;
  const specX = Math.cos(specAngle) * r * 0.45;
  const specY = Math.sin(specAngle) * projY * 0.35;

  // Specular highlight gradient
  const specGrad = ctx.createRadialGradient(specX, specY, 0, specX, specY, r*0.6);
  specGrad.addColorStop(0, 'rgba(255,255,240,0.7)');
  specGrad.addColorStop(0.15, 'rgba(255,250,200,0.35)');
  specGrad.addColorStop(0.4, 'rgba(255,240,160,0.1)');
  specGrad.addColorStop(1, 'rgba(255,240,160,0)');

  // Rim highlight (edge glow)
  const rimGrad = ctx.createRadialGradient(0, 0, r*0.88, 0, 0, r);
  rimGrad.addColorStop(0, 'rgba(255,240,180,0.15)');
  rimGrad.addColorStop(0.7, 'rgba(255,240,180,0)');
  rimGrad.addColorStop(1, metal.rim + '40');

  // Draw main face
  ctx.beginPath();
  ctx.ellipse(0, 0, r, projY, yaw*0.3, 0, Math.PI*2);
  ctx.fillStyle = baseGrad;
  ctx.fill();

  // Draw specular highlight
  ctx.save();
  ctx.beginPath();
  ctx.ellipse(0, 0, r, projY, yaw*0.3, 0, Math.PI*2);
  ctx.clip();
  ctx.fillStyle = specGrad;
  ctx.fillRect(-r, -projY-r, r*2, projY*2+r*2);
  ctx.restore();

  // Draw rim highlight
  ctx.save();
  ctx.beginPath();
  ctx.ellipse(0, 0, r, projY, yaw*0.3, 0, Math.PI*2);
  ctx.clip();
  ctx.fillStyle = rimGrad;
  ctx.fillRect(-r, -projY-r, r*2, projY*2+r*2);
  ctx.restore();

  // Draw emblem on face
  const emScale = Math.abs(cosPitch);
  if(emScale > 0.1){
    ctx.globalAlpha = emScale * 0.9 + 0.1;
    drawEmblem(ctx, 0, 0, r, 'gold', metalFins.gold, emScale * 0.7 + 0.3);
    ctx.globalAlpha = 1;
  }

  // Top edge highlight (rim light)
  const topLight = Math.max(0, Math.cos(pitch));
  if(topLight > 0.1){
    const tlGrad = ctx.createLinearGradient(0, -projY*0.95, 0, -projY*0.6);
    tlGrad.addColorStop(0, `rgba(255,255,240,${topLight*0.5})`);
    tlGrad.addColorStop(1, 'rgba(255,255,240,0)');
    ctx.fillStyle = tlGrad;
    ctx.beginPath();
    ctx.ellipse(0, -projY*0.85, r*0.95, projY*0.15, yaw*0.3, 0, Math.PI);
    ctx.fill();
  }

  // Bottom shadow
  const botShadow = Math.max(0, -Math.cos(pitch));
  if(botShadow > 0.1){
    const bsGrad = ctx.createLinearGradient(0, projY*0.6, 0, projY*0.95);
    bsGrad.addColorStop(0, 'rgba(0,0,0,0)');
    bsGrad.addColorStop(1, `rgba(0,0,0,${botShadow*0.4})`);
    ctx.fillStyle = bsGrad;
    ctx.beginPath();
    ctx.ellipse(0, projY*0.85, r*0.95, projY*0.15, yaw*0.3, 0, Math.PI);
    ctx.fill();
  }

  // Outline ring for definition
  ctx.strokeStyle = metalFins.gold.rim + '60';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.ellipse(0, 0, r, projY, yaw*0.3, 0, Math.PI*2);
  ctx.stroke();

  ctx.restore();
}

function drawBackFaceForHero(ctx, r, t){
  const {yaw, pitch} = getOrientationAt(t);
  const cosPitch = Math.cos(pitch);
  const projY = r * Math.abs(cosPitch);

  if(projY < 1) return;

  ctx.save();

  const metal = metalFins.gold;

  // Back face base gradient (opposite to front)
  const specAngle = yaw * 0.7 + Math.PI * 2.3;
  const specX = Math.cos(specAngle) * r * 0.45;
  const specY = Math.sin(specAngle) * projY * 0.35;

  const baseGrad = ctx.createRadialGradient(
    -r*0.1, r*0.1, r*0.05,
    0, 0, r
  );
  baseGrad.addColorStop(0, metal.faceDark);
  baseGrad.addColorStop(0.5, metal.face);
  baseGrad.addColorStop(1, metal.faceLight);

  // Move highlight based on rotation
  const specGrad = ctx.createRadialGradient(specX, specY, 0, specX, specY, r*0.6);
  specGrad.addColorStop(0, 'rgba(255,240,180,0.5)');
  specGrad.addColorStop(0.15, 'rgba(255,230,150,0.25)');
  specGrad.addColorStop(0.4, 'rgba(255,220,120,0.08)');
  specGrad.addColorStop(1, 'rgba(255,220,120,0)');

  // Draw main face
  ctx.beginPath();
  ctx.ellipse(0, 0, r, projY, -yaw*0.3+Math.PI, 0, Math.PI*2);
  ctx.fillStyle = baseGrad;
  ctx.fill();

  // Specular highlight on back too (opposite side)
  const opAngle = specAngle + Math.PI;
  const opX = Math.cos(opAngle)*r*0.45;
  const opY = Math.sin(opAngle)*projY*0.35;
  const opGrad = ctx.createRadialGradient(opX, opY, 0, opX, opY, r*0.4);
  opGrad.addColorStop(0, 'rgba(255,250,220,0.4)');
  opGrad.addColorStop(0.3, 'rgba(255,240,180,0.1)');
  opGrad.addColorStop(1, 'rgba(255,240,180,0)');

  ctx.save();
  ctx.beginPath();
  ctx.ellipse(0, 0, r, projY, -yaw*0.3+Math.PI, 0, Math.PI*2);
  ctx.clip();
  ctx.fillStyle = opGrad;
  ctx.fillRect(-r, -projY-r, r*2, projY*2+r*2);
  ctx.restore();

  // Draw back face content (denomination) with elliptical distortion
  const emScale = Math.abs(cosPitch);
  if(emScale > 0.1){
    drawBackFaceEmblem(ctx, 0, 0, r, projY, -yaw*0.3+Math.PI, metalFins.gold, emScale * 0.5 + 0.5);
  }

  // Outline
  ctx.strokeStyle = metalFins.gold.rim + '40';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.ellipse(0, 0, r, projY, -yaw*0.3+Math.PI, 0, Math.PI*2);
  ctx.stroke();

  ctx.restore();
}

function drawBackFaceEmblem(ctx,cx,cy,r,projY,rotAngle,metal,alpha){
  ctx.save();
  ctx.globalAlpha = alpha || 1;

  // We need to account for the elliptical distortion
  ctx.scale(1, projY/r);

  const denomTexts = {gold:'50,000 TOKENS',silver:'10,000 TOKENS',bronze:'5,000 TOKENS',black:'100,000 TOKENS'};
  const denom = '50,000 TOKENS'; // hero is gold

  // Outer ring
  ctx.strokeStyle = metal.faceDark + '80';
  ctx.lineWidth = r*0.025 / (projY/r);
  ctx.beginPath(); ctx.arc(0,0,r*0.85,0,Math.PI*2); ctx.stroke();

  // Center decoration
  ctx.strokeStyle = metal.rim + '40';
  ctx.lineWidth = r*0.015 / (projY/r);
  ctx.beginPath(); ctx.arc(0,0,r*0.78,0,Math.PI*2); ctx.stroke();

  // Denomination text - draw on a line
  const fontSize = r * 0.14;
  ctx.fillStyle = metal.faceDark + 'cc';
  ctx.font = `bold ${fontSize}px Georgia`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';

  // Split "50,000" and "TOKENS"
  const parts = denom.split(' ');
  if(parts.length >= 2){
    ctx.font = `bold ${fontSize*1.4}px Georgia`;
    ctx.fillStyle = metal.faceDark + 'dd';
    ctx.fillText(parts[0], 0, -r*0.05);
    ctx.font = `bold ${fontSize*0.8}px Georgia`;
    ctx.fillStyle = metal.faceDark + 'aa';
    ctx.fillText(parts[1].substring(0,5), 0, r*0.18);
  }

  // Top decorative text
  const topText = 'WASTEDTOKEN';
  ctx.font = `${fontSize*0.35}px Georgia`;
  ctx.fillStyle = metal.faceDark + '70';
  ctx.fillText(topText, 0, -r*0.42);

  // Bottom decorative text
  const botText = 'MINT · ';
  ctx.fillText(botText, 0, r*0.42);

  // Star decoration
  drawStar(ctx, 0, -r*0.35, r*0.035, 5);

  ctx.restore();
}

/* ======================== ANIMATION ======================== */

let animT = 0;
let animId = null;
let paused = false;
let currentT = 0; // for setTime API
let animSpeed = 1/6; // seconds per full loop (roughly)
let lastFrameTime = 0;

function animate(timestamp){
  if(paused) return;

  if(!lastFrameTime) lastFrameTime = timestamp;
  const dt = (timestamp - lastFrameTime) / 1000;
  lastFrameTime = timestamp;

  animT += dt * animSpeed;
  if(animT > 1) animT -= 1;

  render();
  animId = requestAnimationFrame(animate);
}

function render(){
  const w = W(), h = H();
  ctx.clearRect(0,0,w,h);

  // Simple backdrop - dark gradient
  const bgGrad = ctx.createRadialGradient(w/2,h/2,0,w/2,h/2,w*0.7);
  bgGrad.addColorStop(0,'#151520');
  bgGrad.addColorStop(1,'#0a0a0f');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0,0,w,h);

  // Subtle radial glow behind coin
  const glowGrad = ctx.createRadialGradient(CX(),CY(),coinR()*0.5,CX(),CY(),coinR()*1.8);
  glowGrad.addColorStop(0,'rgba(201,168,76,0.08)');
  glowGrad.addColorStop(1,'rgba(201,168,76,0)');
  ctx.fillStyle = glowGrad;
  ctx.fillRect(0,0,w,h);

  // Draw the coin - ensure it doesn't touch edges
  const pad = 30;
  const maxR = Math.min((w-pad*2)/2, (h-pad*2)/2);
  const r = coinR();

  if(r > maxR) return; // safety

  renderCoinAtT(ctx, CX(), CY(), r, currentT);
}

function renderCoinAtT(ctx,cx,cy,r,t){
  const {yaw,pitch} = getOrientationAt(t);
  const normal = vec3(0,0,1);
  let n = rotateY(normal,yaw);
  n = rotateX(n,pitch);

  const frontVis = Math.max(0,n.z);
  const backVis = Math.max(0,-n.z);

  // Save context for clipping ellipse
  ctx.save();

  // BACK face (draw first)
  if(backVis > 0.01){
    drawBackFaceAtT(ctx,cx,cy,r,t);
  }

  // EDGE / REEDS
  drawEdgeAtT(ctx,cx,cy,r,yaw,pitch);

  // FRONT face (draw last, on top)
  if(frontVis > 0.01){
    drawFrontFaceAtT(ctx,cx,cy,r,t);
  }

  ctx.restore();
}

function drawBackFaceAtT(ctx,cx,cy,r,t){
  const {yaw,pitch} = getOrientationAt(t);
  const cosP = Math.cos(pitch);
  const projY = r * Math.abs(cosP);
  if(projY < 2) return;

  const metal = metalFins.gold;
  const specAngle = yaw*0.7 + Math.PI*2.3;
  const specX = Math.cos(specAngle)*r*0.45;
  const specY = Math.sin(specAngle)*projY*0.35;

  // Clip to elliptical face shape
  ctx.save();
  ctx.beginPath();
  ctx.ellipse(cx,cy,r,projY,-yaw*0.3+Math.PI,0,Math.PI*2);
  ctx.clip();

  // Base gradient - note it's "inside-out" from front
  const baseGrad = ctx.createRadialGradient(
    cx-r*0.15, cy+r*0.15, r*0.05,
    cx, cy, r*1.2
  );
  baseGrad.addColorStop(0, metal.faceDark);
  baseGrad.addColorStop(0.4, metal.faceDark);
  baseGrad.addColorStop(0.7, metal.face);
  baseGrad.addColorStop(1, metal.faceLight);
  ctx.fillStyle = baseGrad;
  ctx.fillRect(cx-r, cy-projY-r*2, r*2, projY*2+r*4);

  // Specular highlight (opposite side of front's)
  const opAngle = specAngle + Math.PI;
  const opX = cx+Math.cos(opAngle)*r*0.45;
  const opY = cy+Math.sin(opAngle)*projY*0.35;
  const opGrad = ctx.createRadialGradient(opX,opY,0,opX,opY,r*0.5);
  opGrad.addColorStop(0,'rgba(255,240,180,0.5)');
  opGrad.addColorStop(0.3,'rgba(255,230,150,0.15)');
  opGrad.addColorStop(1,'rgba(255,220,120,0)');
  ctx.fillStyle = opGrad;
  ctx.fillRect(cx-r, cy-projY-r*2, r*2, projY*2+r*4);

  // Denomination text
  ctx.scale(1, projY/r);
  const denom = '50,000';
  ctx.fillStyle = metal.faceDark+'cc';
  ctx.font = `bold ${r*0.16}px Georgia`;
  ctx.textAlign='center'; ctx.textBaseline='middle';
  ctx.fillText(denom, cx, cy - r*0.05);

  const tok = 'TOKENS';
  ctx.font = `bold ${r*0.07}px Georgia`;
  ctx.fillStyle = metal.faceDark+'99';
  ctx.fillText(tok, cx, cy + r*0.22);

  // Decorative ring
  ctx.strokeStyle = metal.rim+'50';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.arc(cx,cy,r*0.82,0,Math.PI*2);
  ctx.stroke();

  ctx.restore(); // un-clip

  // Outline
  ctx.strokeStyle = metalFins.gold.rim+'30';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.ellipse(cx,cy,r,projY,-yaw*0.3+Math.PI,0,Math.PI*2);
  ctx.stroke();
}

function drawEdgeAtT(ctx,cx,cy,r,yaw,pitch){
  const edgeVis = Math.abs(Math.sin(pitch));
  if(edgeVis < 0.03) return;

  ctx.save();

  // Draw the cylindrical edge band
  const edgeWidth = r * 0.06; // thickness of coin in local Z

  // Compute visible portions
  const cosYaw = Math.cos(yaw);
  const sinYaw = Math.sin(yaw);

  // The edge is a narrow band around the perimeter
  // When tilted, we see it as an extended rim
  const reeds = 72;
  for(let i=0;i<reeds;i++){
    const a = (i/reeds)*Math.PI*2;
    const cosA = Math.cos(a);
    const sinA = Math.sin(a);

    // Determine if this part of the edge is visible
    const viewDot = cosA * sinYaw - sinA * cosYaw * 0.3;
    if(viewDot < -0.2) continue; // facing away

    // Position on screen
    const px = cx + cosA * r * 0.96;
    const py = cy + sinA * r * Math.abs(Math.cos(pitch)) * 0.96;

    // Reed thickness (visible when tilted)
    const reedW = edgeWidth * edgeVis;

    if(reedW > 1){
      ctx.fillStyle = metalFins.gold.rim + (40 + Math.floor(viewDot*200)).toString(16).padStart(2,'0');
      ctx.fillRect(px - reedW/2, py - 1, reedW+1, 2);
    }
  }

  // Top and bottom rim lines to define the edge boundaries
  const topLine = cy - r * Math.abs(Math.cos(pitch)) * 0.94;
  const botLine = cy + r * Math.abs(Math.cos(pitch)) * 0.94;

  ctx.strokeStyle = metalFins.gold.rim + '25';
  ctx.lineWidth = edgeWidth * edgeVis;
  ctx.beginPath();
  ctx.moveTo(cx-r*0.98, topLine);
  ctx.lineTo(cx+r*0.98, topLine);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(cx-r*0.98, botLine);
  ctx.lineTo(cx+r*0.98, botLine);
  ctx.stroke();

  ctx.restore();
}

function drawFrontFaceAtT(ctx,cx,cy,r,t){
  const {yaw,pitch} = getOrientationAt(t);
  const cosP = Math.cos(pitch);
  const projY = r * Math.abs(cosP);
  if(projY < 2) return;

  const metal = metalFins.gold;

  // Clip to elliptical face shape
  ctx.save();
  ctx.beginPath();
  ctx.ellipse(cx,cy,r,projY,yaw*0.3,0,Math.PI*2);
  ctx.clip();

  // === SPECULAR HIGHLIGHT - the raking light effect ===
  const specAngle = yaw * 0.7 + Math.PI * 0.5;
  const hlX = cx + Math.cos(specAngle) * r * 0.48;
  const hlY = cy + Math.sin(specAngle) * projY * 0.38;

  // Main specular highlight
  const specGrad = ctx.createRadialGradient(hlX, hlY, 0, hlX, hlY, r*0.5);
  specGrad.addColorStop(0, 'rgba(255,255,240,0.75)');
  specGrad.addColorStop(0.12, 'rgba(255,248,200,0.35)');
  specGrad.addColorStop(0.35, 'rgba(255,235,150,0.1)');
  specGrad.addColorStop(1, 'rgba(255,230,140,0)');

  // Secondary smaller highlight for realism
  const secAngle = yaw * 0.7 + Math.PI * 0.5 + 0.4;
  const hlX2 = cx + Math.cos(secAngle)*r*0.35;
  const hlY2 = cy + Math.sin(secAngle)*projY*0.28;
  const specGrad2 = ctx.createRadialGradient(hlX2,hlY2,0,hlX2,hlY2,r*0.15);
  specGrad2.addColorStop(0,'rgba(255,255,245,0.3)');
  specGrad2.addColorStop(1,'rgba(255,255,245,0)');

  // Metallic base gradient that shifts with yaw
  const hlOffsetX = Math.cos(yaw*0.5)*r*0.15;
  const hlOffsetY = Math.sin(yaw*0.3)*projY*0.1;

  const baseGrad = ctx.createRadialGradient(
    cx+hlOffsetX, cy+hlOffsetY, r*0.05,
    cx-r*0.2, cy-r*0.2, r*1.3
  );
  baseGrad.addColorStop(0, metal.faceLight);
  baseGrad.addColorStop(0.3, metal.face);
  baseGrad.addColorStop(0.75, metal.faceDark);
  baseGrad.addColorStop(1, metal.faceDark);

  // Render layers
  ctx.fillStyle = baseGrad;
  ctx.fillRect(cx-r, cy-projY-r*2, r*2, projY*2+r*4);

  ctx.fillStyle = specGrad;
  ctx.fillRect(cx-r, cy-projY-r*2, r*2, projY*2+r*4);

  ctx.fillStyle = specGrad2;
  ctx.fillRect(cx-r, cy-projY-r*2, r*2, projY*2+r*4);

  // Edge glow (light catching the rim)
  const edgeGlow = Math.max(0, Math.sin(pitch));
  if(edgeGlow > 0.1){
    const topGlowGrad = ctx.createLinearGradient(cx,cy-projY-r,cx,cy-projY);
    topGlowGrad.addColorStop(0,'rgba(255,240,180,0)');
    topGlowGrad.addColorStop(1,`rgba(255,240,180,${edgeGlow*0.3})`);
    ctx.fillStyle = topGlowGrad;
    ctx.fillRect(cx-r,cy-projY,r*2,projY*0.08);

    const botGlowGrad = ctx.createLinearGradient(cx,cy+projY,cx,cy+projY+r);
    botGlowGrad.addColorStop(0,`rgba(255,240,180,${edgeGlow*0.3})`);
    botGlowGrad.addColorStop(1,'rgba(255,240,180,0)');
    ctx.fillStyle = botGlowGrad;
    ctx.fillRect(cx-r,cy+projY*0.92,r*2,projY*0.08);
  }

  // === EMBLEM on front face ===
  const emAlpha = Math.abs(cosP)*0.5 + 0.5;
  drawEmblem(ctx, cx, cy, r, 'gold', metal, emAlpha);

  ctx.restore(); // un-clip

  // Outline ring (drawn outside clip)
  ctx.strokeStyle = metalFins.gold.rim+'60';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.ellipse(cx,cy,r,projY,yaw*0.3,0,Math.PI*2);
  ctx.stroke();

  // Inner ring decoration
  ctx.strokeStyle = metalFins.gold.faceDark+'40';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.ellipse(cx,cy,r*0.97,projY*0.97,yaw*0.3,0,Math.PI*2);
  ctx.stroke();
}

/* ======================== EDITION COIN RENDERING ======================== */

function renderEditionCoin(canvas, type){
  const cCtx = canvas.getContext('2d');
  const w = canvas.width;
  const h = canvas.height;
  const cx = w/2;
  const cy = h/2;
  const r = w * 0.4;

  // Background
  const bgGrad = cCtx.createRadialGradient(cx,cy,0,cx,cy,w*0.7);
  bgGrad.addColorStop(0,'#1e1e28');
  bgGrad.addColorStop(1,'#14141a');
  cCtx.fillStyle = bgGrad;
  cCtx.fillRect(0,0,w,h);

  // Subtle glow behind coin
  const glow = metalFins[type] ? metalFins[type].rim : '#888';
  const coinGlow = cCtx.createRadialGradient(cx,cy,r*0.5,cx,cy,r*1.8);
  coinGlow.addColorStop(0, glow+'30');
  coinGlow.addColorStop(1, glow+'00');
  cCtx.fillStyle = coinGlow;
  cCtx.fillRect(0,0,w,h);

  // Draw static (non-rotated) version of the coin
  drawFrontFaceAtT(cCtx,cx,cy,r,type);
}

function drawFrontFaceAtT(ctx,cx,cy,r,type){
  const t = performance.now() * 0.0003; // slight variation for each edition coin
  const yaw = type === 'bronze' ? 0 : type === 'silver' ? Math.PI*0.15 : type === 'gold' ? -Math.PI*0.25 : Math.PI*0.4;
  const pitch = type === 'black' ? Math.PI*0.3 : 0.05; // black slightly tilted to show edge

  const cosP = Math.cos(pitch);
  const projY = r * Math.abs(cosP);

  const metal = metalFins[type] || metalFins.gold;

  ctx.save();
  ctx.beginPath();
  ctx.ellipse(cx,cy,r,projY,yaw*0.3,0,Math.PI*2);
  ctx.clip();

  // Specular highlight position
  const specAngle = yaw * 0.7 + Math.PI * 0.5;
  const hlX = cx + Math.cos(specAngle)*r*0.48;
  const hlY = cy + Math.sin(specAngle)*projY*0.38;

  // Main specular
  const specGrad = ctx.createRadialGradient(hlX,hlY,0,hlX,hlY,r*0.5);
  specGrad.addColorStop(0,'rgba(255,255,240,0.6)');
  specGrad.addColorStop(0.12,'rgba(255,248,200,0.3)');
  specGrad.addColorStop(0.35,'rgba(255,235,150,0.08)');
  specGrad.addColorStop(1,'rgba(255,230,140,0)');

  // Metallic base gradient
  const hlOffX = Math.cos(yaw*0.5)*r*0.12;
  const hlOffY = Math.sin(yaw*0.3)*projY*0.1;

  let baseGrad;
  if(type === 'black'){
    baseGrad = ctx.createRadialGradient(cx+hlOffX,cy+hlOffY,r*0.05, cx-r*0.2,cy-r*0.2,r*1.3);
    baseGrad.addColorStop(0,'#4a4a4a');
    baseGrad.addColorStop(0.3,'#2a2a2a');
    baseGrad.addColorStop(0.7,'#151515');
    baseGrad.addColorStop(1,'#0a0a0a');
  } else if(type === 'silver'){
    baseGrad = ctx.createRadialGradient(cx+hlOffX,cy+hlOffY,r*0.05, cx-r*0.2,cy-r*0.2,r*1.3);
    baseGrad.addColorStop(0,'#e8e8e8');
    baseGrad.addColorStop(0.3,'#c0c0c0');
    baseGrad.addColorStop(0.7,'#909090');
    baseGrad.addColorStop(1,'#606060');
  } else {
    baseGrad = ctx.createRadialGradient(cx+hlOffX,cy+hlOffY,r*0.05, cx-r*0.2,cy-r*0.2,r*1.3);
    baseGrad.addColorStop(0, metal.faceLight);
    baseGrad.addColorStop(0.3, metal.face);
    baseGrad.addColorStop(0.75, metal.faceDark);
    baseGrad.addColorStop(1, metal.faceDark);
  }

  ctx.fillStyle = baseGrad;
  ctx.fillRect(cx-r,cy-projY-r*2,r*2,projY*2+r*4);

  ctx.fillStyle = specGrad;
  ctx.fillRect(cx-r,cy-projY-r*2,r*2,projY*2+r*4);

  // Edge glow
  const edgeGlow = Math.max(0, Math.sin(pitch));
  if(edgeGlow > 0.1){
    const topGlow = ctx.createLinearGradient(cx,cy-projY-r,cx,cy-projY);
    topGlow.addColorStop(0,'rgba(255,240,180,0)');
    topGlow.addColorStop(1,`rgba(255,240,180,${edgeGlow*0.3})`);
    ctx.fillStyle = topGlow;
    ctx.fillRect(cx-r,cy-projY,r*2,projY*0.08);
  }

  // Emblem on front face
  const emAlpha = Math.abs(cosP)*0.5 + 0.5;
  drawEmblem(ctx,cx,cy,r,type,metal,emAlpha);

  ctx.restore();

  // Outline
  ctx.strokeStyle = metalFins[type] ? metalFins[type].rim+'80' : '#aaa80';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.ellipse(cx,cy,r,projY,yaw*0.3,0,Math.PI*2);
  ctx.stroke();
}

